      const around = (H(c.x + 45, c.z) + H(c.x - 45, c.z) + H(c.x, c.z + 45) + H(c.x, c.z - 45)) / 4;
      const score = c.y - around - spreadAt(c.x, c.z, 10) * 1.2;
