  lynx: { hp: 45, drop: [['fourrure', 1, 2], ['croc', 1, 1]] }, otter: { hp: 15, drop: [['fourrure', 1, 1]] }, frog: { hp: 2, drop: [['viande', 0, 1, 0.5]] },
