  swan: { hp: 14, drop: [['plume', 3, 4], ['viande', 1, 2]] }, pheasant: { hp: 6, drop: [['viande', 1, 2], ['plume', 2, 3]] }, partridge: { hp: 5, drop: [['viande', 1, 1], ['plume', 1, 1]] },
