  if (p.riding) { p.stamina = 1; sound.splash && sound.splash(); ui.subtitle('', '(Votre monture boit longuement. Elle souffle, puis relève la tête.)', 3); }
  else ui.subtitle('', '(L’eau est fraîche. Pour les chevaux, surtout.)', 2.5);
