HOOKS.fx.push((fx, tint) => { if (strange.redRain > 0) { const k = Math.min(1, strange.redRain / 5, (45 - strange.redRain) / 4); tint[0] = 0.7; tint[1] = 0.05; tint[2] = 0.04; tint[3] = Math.max(tint[3], 0.28 * k); } });
