// ---- 11-zzterra.js
// ============================================================================
//  LA PELLE TERRAFORME : clic gauche creuse (le sol s'abaisse d'un quart de
//  mètre, on récupère une motte de terre — ou du sable), clic droit remblaie
//  (avec la terre ou le sable qu'on porte), accroupi on nivelle à la hauteur
//  de ses pieds. Éboulis, secrets, cartes au trésor et terre remuée passent
//  en premier. Creuser plus bas qu'avant fait parfois remonter une trouvaille ;
//  sous le niveau de l'eau, le trou se remplit (on peut creuser une mare).
//  Pas en ville, ni contre un bâtiment, un objet posé ou des cultures.
//  Le sol retourné redevient herbe au bout de trois jours.
//  Sauvegarde : décalage de hauteur par sommet de la grille (2 m), ±3 m.
// ============================================================================
const TERRA_STEP = 0.25, TERRA_MAX = 3;
const TERRA_FREE = new Set(['trou', 'fouille', 'traces', 'sang', 'coffre_tresor', 'ossements']);
const TERRA_WHY = {
  roche: '(De la roche. La pelle ne mord pas.)', ville: '(Pas en ville : ces pavés-là ont un propriétaire.)', bati: '(Trop près d’une construction : ça finirait par s’effondrer.)',
  objet: '(Il y a quelque chose de posé là.)', culture: '(Vous abîmeriez les cultures.)', bord: '',
};
const terra = {
  sayT: 0, lastWhy: '',
  // sommet de la grille le plus proche du point visé
  vertexAt(eye, f) {
    const w = game.world, th = w.raycastTerrain(eye, f, 4.6);
    if (!th) return null;
    const bh = w.raycastBlocks(eye, f, th.t);
    if (bh && !bh.block.hidden) return null;
    const i = Math.round(th.x / w.cell), j = Math.round(th.z / w.cell), k = j * w.W + i;
    return { i, j, k, x: i * w.cell, z: j * w.cell, y: w.heights[k] };
  },
  blocked(w, v) {
    const { i, j, x, z } = v;
    if (i < 3 || j < 3 || i > w.N - 3 || j > w.N - 3) return 'bord';
    const T = w.townInfo;
    if (T && Math.max(Math.abs(x - T.x), Math.abs(z - T.z)) < 62) return 'ville';
    const m = w.mats[v.k];
    if (m === M_ROCK || m === M_COBBLE) return 'roche';
    const h = w.heights[v.k];
    let bati = false;
    w.query(x, z, 5, null, (b) => {
      if (bati || b.under || b.y > h + 4 || b.y + b.sy < h - 2.5) return;
      const [lx, lz] = World.blockLocal(b, x, z);
      if (Math.abs(lx) < b.sx / 2 + 2.3 && Math.abs(lz) < b.sz / 2 + 2.3) bati = true;
    });
    if (bati) return 'bati';
    for (const p of w.props) if (w.live(p) && !TERRA_FREE.has(p.id) && Math.abs(p.x - x) < 2.3 && Math.abs(p.z - z) < 2.3 && Math.abs(p.y - h) < 3) return 'objet';
    for (let dz = -2; dz <= 1; dz++) for (let dx = -2; dx <= 1; dx++) { const c = farm.s.crops[(Math.floor(x) + dx) + ',' + (Math.floor(z) + dz)]; if (c && (c.c || c.tree)) return 'culture'; }
    return null;
  },
  refuse(why, held) {
    if (why === 'roche') { sound.shovelHit && sound.shovelHit(); play.cool = 0.6; }
    else sound.click();
    if (TERRA_WHY[why] && (!held || why !== this.lastWhy || performance.now() > this.sayT)) { ui.subtitle('', TERRA_WHY[why], 2); this.sayT = performance.now() + 2500; this.lastWhy = why; }
  },
  // change la hauteur d'un sommet (dh en mètres) ; renvoie le changement effectif
  edit(w, v, dh, mat) {
    const s = farm.s, T = s.terra || (s.terra = {}), k = v.k;
    const cur = T[k] || 0, nv = Math.round(clamp(cur + dh, -TERRA_MAX, TERRA_MAX) * 100) / 100;
    if (Math.abs(nv - cur) < 0.005) return 0;
    w.heights[k] += nv - cur;
    if (Math.abs(nv) < 0.005) delete T[k]; else T[k] = nv;
    // sol retourné : de la terre (ou du sable), l'herbe repoussera
    const m = w.mats[k], want = mat ?? (m === M_SAND ? M_SAND : M_DIRT);
    const TM = s.terraM || (s.terraM = {});
    if (m !== want) { if (!TM[k]) TM[k] = [m, s.day]; w.mats[k] = want; w.markMats(v.i, v.j, v.i, v.j); }
    if (TM[k]) TM[k][1] = s.day;
    // la terre labourée vide autour disparaît (elle a été remuée)
    for (let dz = -2; dz <= 1; dz++) for (let dx = -2; dx <= 1; dx++) { const key = (Math.floor(v.x) + dx) + ',' + (Math.floor(v.z) + dz), c = s.crops[key]; if (c && !c.c && !c.tree) delete s.crops[key]; }
    this.mark(w, v);
    return nv - cur;
  },
  mark(w, v) {
    const { i, j } = v, d = w.dirtyHeights, i0 = Math.max(0, i - 1), j0 = Math.max(0, j - 1), i1 = Math.min(w.N, i + 1), j1 = Math.min(w.N, j + 1);
    w.dirtyHeights = d ? [Math.min(d[0], i0), Math.min(d[1], j0), Math.max(d[2], i1), Math.max(d[3], j1)] : [i0, j0, i1, j1];
    // herbes, fleurs, arbres posés sur ce sol : à redessiner à la bonne hauteur
    const G = w.objectsGrid(), C = G.C;
    let near = false;
    for (let gz = Math.floor((v.z - 3) / C); gz <= Math.floor((v.z + 3) / C) && !near; gz++) for (let gx = Math.floor((v.x - 3) / C); gx <= Math.floor((v.x + 3) / C) && !near; gx++) {
      const cell = G.cells[clamp(gz, 0, G.gw - 1) * G.gw + clamp(gx, 0, G.gw - 1)];
      if (cell) for (const oi of cell) { const o = w.objects[oi]; if (o.y === undefined && Math.abs(o.x - v.x) < 2.2 && Math.abs(o.z - v.z) < 2.2) { near = true; break; } }
    }
    if (near) w.objectsDirty = true;
    farm.dirtyProps = true;
  },
  fx(v, sand, k) {
    sound.shovel && sound.shovel(k || 1);
    puffAt(v.x, game.world.heights[v.k] + 0.1, v.z, sand ? [200, 180, 120] : [96, 68, 44], 10, 1.8, false);
  },
  // ---------------------------------------------------------------- creuser
  dig(eye, f, held) {
    const w = game.world, s = farm.s, v = this.vertexAt(eye, f);
    if (!v) { sound.impact && sound.impact('soft'); return; }
    const why = this.blocked(w, v);
    if (why) return this.refuse(why, held);
    const sand = w.mats[v.k] === M_SAND, before = w.heights[v.k];
    if (!this.edit(w, v, -TERRA_STEP)) { if (!held) ui.subtitle('', '(Plus profond, la terre s’effondre à mesure.)', 2); sound.shovel && sound.shovel(0.5); return; }
    this.fx(v, sand);
    const item = sand ? 'sable' : 'terre';
    farm.give(item, 1); play.flyer(item, [v.x, w.heights[v.k] + 0.3, v.z], 1);
    // trouvailles : seulement en creusant plus bas qu'on ne l'avait jamais fait ici
    const D = s.terraD || (s.terraD = {}), cur = (s.terra && s.terra[v.k]) || 0;
    if (cur < (D[v.k] ?? 0) - 0.001) {
      D[v.k] = cur;
      const h = npcs.hour(), b = game.biomeAt([v.x, v.y, v.z]), night = h >= 21 || h < 4;
      let loot = null;
      if (sand) { if (Math.random() < 0.12) loot = rollLoot('sable'); }
      else if (night && (b === 'foret' || b === 'bouleaux') && Math.random() < 0.05) { loot = [['mandragore', 1]]; sound.scream2 && sound.scream2(); ui.subtitle('', '(La racine hurle en sortant de terre. Puis plus rien.)', 3.5); strange.glitchT = 0.3; }
      else if (Math.random() < 0.13) loot = rollLoot('pelle');
      for (const [k, n] of loot || []) { if (k === 'argent') { farm.earn(n); continue; } farm.give(k, n); play.flyer(k, [v.x, w.heights[v.k] + 0.4, v.z], n); }
    }
    if (before >= w.waterLevel - 0.05 && w.heights[v.k] < w.waterLevel - 0.05) { sound.splash(); ui.subtitle('', '(L’eau remonte au fond du trou.)', 2.5); }
    s.stats.holes = (s.stats.holes || 0) + 1;
  },
  // ---------------------------------------------------------------- remblayer (clic droit)
  raise(eye, f) {
    const w = game.world, v = this.vertexAt(eye, f);
    play.swingT = 0.3; play.cool = 0.42;
    if (!v) return;
    const src = farm.count('terre') ? 'terre' : farm.count('sable') ? 'sable' : null;
    if (!src) { ui.subtitle('', '(Il vous faut de la terre à remettre : creusez ailleurs d’abord.)', 2.5); sound.click(); return; }
    const why = this.blocked(w, v);
    if (why) return this.refuse(why);
    if (!this.edit(w, v, TERRA_STEP, src === 'sable' ? M_SAND : M_DIRT)) { ui.subtitle('', '(Plus haut, la terre s’éboule.)', 2); return; }
    farm.take(src, 1);
    this.fx(v, src === 'sable', 0.8);
  },
  // ---------------------------------------------------------------- niveler (accroupi) : à la hauteur de ses pieds
  level(eye, f, held) {
    const w = game.world, p = game.player, v = this.vertexAt(eye, f);
    if (!v) return;
    const why = this.blocked(w, v);
    if (why) return this.refuse(why, held);
    const diff = p.pos[1] - w.heights[v.k];
    if (Math.abs(diff) < 0.04) { if (!held) ui.subtitle('', '(C’est de niveau.)', 1.2); sound.click(); return; }
    const dh = clamp(diff, -TERRA_STEP, TERRA_STEP);
    const src = farm.count('terre') ? 'terre' : farm.count('sable') ? 'sable' : null;
    if (dh > 0 && !src) { ui.subtitle('', '(Il manque de la terre pour remblayer.)', 2); sound.click(); return; }
    const got = this.edit(w, v, dh);
    if (!got) return;
    if (got > 0) farm.take(src, 1); else if (-got > 0.12) { farm.give('terre', 1); play.flyer('terre', [v.x, w.heights[v.k] + 0.3, v.z], 1); }
    this.fx(v, false, 0.8);
  },
  // ---------------------------------------------------------------- chargement, repousse
  apply(w) {
    const s = farm.s, T = s.terra || {}, M = s.terraM || {};
    for (const k in T) w.heights[+k] += T[k];
    for (const k in M) w.mats[+k] = w.mats[+k] === M_SAND ? M_SAND : M_DIRT;
  },
  regrow() {
    const s = farm.s, w = game.world, M = s.terraM || {};
    for (const k in M) {
      if (s.day - M[k][1] < 3) continue;
      const kk = +k, i = kk % w.W, j = (kk / w.W) | 0;
      w.mats[kk] = M[k][0]; w.markMats(i, j, i, j);
      delete M[k];
    }
  },
};

// la pelle : les secrets d'abord (éboulis, trésors, terre remuée), puis on retourne le sol
dig.at = function (eye, f, held) {
  const w = game.world, s = farm.s;
  play.swingT = 0.32; play.cool = held ? 0.45 : 0.5;
  const eb = (w.inter || []).find((it) => it.kind === 'eboulis' && !this.caveOpen(it.data.cave) && Math.hypot(it.x - eye[0], it.z - eye[2]) < 3.6 && this.facing(eye, f, it, 0.55));
  if (eb) return this.rubble(eb);
  const c = play.cellAt(eye, f);
  if (c) {
    for (const q of w.secrets || []) { if (s.flags['secret_' + q.id]) continue; if (Math.hypot(q.x - c.x, q.z - c.z) < q.r) return this.secretDig(q, c); }
    for (const m of s.maps || []) { if (m.found || Math.hypot(m.x - c.x, m.z - c.z) > 2.6) continue; return this.mapDig(m, c); }
    const d0 = (w.inter || []).find((it) => it.kind === 'dig' && !s.flags['dug_' + it.id] && Math.hypot(it.x - c.x, it.z - c.z) < 1.6 && (!it.data.envers || strange.inEnvers()));
    if (d0) { play.digUp(d0); if (Math.random() < 0.5) { const L = rollLoot('pelle'); for (const [k, n] of L) if (k !== 'argent') { farm.give(k, n); play.flyer(k, [c.x, c.y + 0.4, c.z], n); } } return; }
  }
  if (game.player.crouch > 0.5) return terra.level(eye, f, held);
  return terra.dig(eye, f, held);
};
HOOKS.secondary.push((eye, basis, it) => {
  if (!it || it.tool !== 'pelle') return false;
  if (play.cool > 0) return true;
  terra.raise(eye, basis.f);
  return true;
});
{
  const _start = farm.start;
  farm.start = async function (saved, seed, progress) {
    const w = await _start.call(this, saved, seed, progress);
    terra.apply(w);
    if (typeof builds !== 'undefined') builds.apply(w);
    return w;
  };
}
HOOKS.day.push(() => terra.regrow());

// ---- 11-zzvallee.js
// ============================================================================
//  LA VALLÉE VIVANTE
//  - crues : quand il pleut longtemps, l'eau monte (prés du bas, berges, marais),
//    noie les cultures trop basses, fait flotter les barques, puis se retire ;
//  - orages : la foudre frappe les grands arbres (ils restent foudroyés) ; les
//    jours de canicule, un « orage sec » peut éclater en fin d'après-midi ;
//  - incendies : le feu prend dans un arbre frappé, gagne ses voisins (le vent le
//    pousse), s'arrête aux prés, aux chemins, à l'eau, sous la pluie ou sous
//    l'arrosoir ; il reste des troncs noircis ;
//  - montagne : il y neige ; il y fait froid (la faim vient plus vite ; la nuit ou
//    sous la neige, sans feu ni toit, le froid tue) ; on tombe dans les crevasses ;
//  - les signes à relever (carnet dans l'onglet Légendes), le refuge du col, la
//    pêche dans le trou de glace, les textes laissés çà et là, les fruits des
//    nouveaux arbres, les restes au fond des crevasses (une seule fouille).
// ============================================================================
WEATHER_PRESETS.dry = { cloud: 0.85, rain: 0.03, storm: 1, fog: 0.04, frost: 0, heat: 0.4 };
WEATHER_NAMES.dry = 'Orage sec'; WEATHER_ICONS.dry = '⚡'; DAY_KIND.dry = 'orage';
{
  const _plan = weather.dayPlan.bind(weather);
  // les jours de canicule, parfois, un orage sec (tirage à part : le reste du programme ne change pas)
  weather.dayPlan = function (seed, day) {
    const P = _plan(seed, day);
    if (P.heat && day > 2) {
      const r = mulberry32(seed * 17 + day * 31);
      if (r() < 0.4) { const h = 15 + r() * 3; P.plan.push([h, 'dry'], [h + 1.5 + r() * 1.5, 'cloudy']); P.plan.sort((a, b) => a[0] - b[0]); P.storm = true; P.dry = true; }
    }
    return P;
  };
}
// ce qui brûle (le chêne millénaire, lui, ne brûle pas)
const FLAMMABLE = new Set(['oak', 'pine', 'birch', 'apple', 'deadtree', 'bush', 'berry', 'fern', 'tallgrass', 'heather', 'lavender', 'hetre', 'chataignier', 'noyer', 'saule', 'peuplier',
  'sapin', 'meleze', 'if', 'tilleul', 'erable', 'cerisier', 'poirier', 'prunier', 'aulne', 'houx', 'foudroye', 'eglantier', 'sureau']);
const STRIKE_TREES = new Set(['oak', 'pine', 'birch', 'apple', 'hetre', 'chataignier', 'noyer', 'peuplier', 'sapin', 'meleze', 'tilleul', 'erable', 'saule', 'aulne', 'sapin_neige', 'deadtree']);

// ---------------------------------------------------------------- les signes
const SIGIL_TEXT = {
  mere: { titre: 'Le signe de la Mère', faith: 'anciens', texte: 'Un cercle posé sur une croix. On le trouve au bord des champs, sur les linteaux des granges, au fond des pétrins. C’est la Mère qui donne et qui reprend : on lui laisse la première gerbe, et on ne lui prend jamais la dernière.' },
  dame: { titre: 'Le croissant de la Dame', faith: 'anciens', texte: 'Une lune couchée au-dessus de deux vagues. La Dame du lac garde ce qui tombe dans l’eau : les bagues, les serments, les noyés. Les nuits où la lune a cette forme-là, on ne se baigne pas.' },
  cerf: { titre: 'Les bois du Cerf', faith: 'anciens', texte: 'Des bois de cerf, et entre eux une petite lumière. Le Cerf blanc marche entre les mondes. Ceux qui l’ont vu ne chassent plus jamais ; on ne sait pas s’ils ne veulent plus, ou s’ils ne peuvent plus.' },
  dessous: { titre: 'Le signe de ceux d’en dessous', faith: 'dessous', texte: 'Une ligne, et sous la ligne un triangle renversé qui prend racine. Ce qui est sous la terre n’est pas mort, dit ce signe : cela attend. On le grave là où l’on a creusé trop profond.' },
  croix: { titre: 'La croix cerclée', faith: 'eglise', texte: 'Une croix dans un anneau, comme on en taillait avant les églises de pierre. Le curé dit que c’est une croix comme les autres. L’anneau, lui, est bien plus vieux que la croix.' },
  treize: { titre: 'Les Treize', faith: 'dessous', texte: 'Treize traits autour d’un cercle, et une pierre au milieu. Ils étaient treize à monter au col, une nuit d’hiver ; il en est redescendu douze. Le treizième est resté là-haut, pour garder le passage. On ne sait plus de quoi.' },
  soleil: { titre: 'Le soleil des moissons', faith: 'anciens', texte: 'Un soleil à huit rayons. On le traçait au seuil des maisons à la Saint-Jean, pour que la lumière ne s’en aille pas. Les jours raccourcissent quand même, mais on n’y pense plus.' },
  spirale: { titre: 'La spirale', faith: 'dessous', texte: 'Une spirale de trois tours, qui ne commence nulle part. Personne ne se souvient de la religion qui la traçait. Sur le glacier, quelqu’un la refait chaque hiver, et personne ne l’a jamais vu faire.' },
  main: { titre: 'La main ouverte', faith: null, texte: 'Une main aux doigts serrés, peinte à l’ocre. Les mineurs la peignaient pour dire « par ici, la sortie » : les doigts montrent le chemin. Les plus vieilles, dit-on, sont plus anciennes que la mine elle-même.' },
  corne: { titre: 'Les cornes', faith: 'anciens', texte: 'Un croissant de cornes posé sur un cercle. Le Cornu des bois, le maître des bêtes : on lui doit une bête sur dix, et le silence en forêt.' },
  noeud: { titre: 'Le nœud sans fin', faith: 'dessous', texte: 'Trois boucles prises dans un cercle, sans début ni fin. Ceux qui le gravent se disent « liés » : liés entre eux, liés à la vallée, liés même après la mort. On ne sait pas s’il faut s’en réjouir.' },
  oeil: { titre: 'L’œil', faith: 'dessous', texte: 'Un œil ouvert, qui pleure trois larmes. Il ne dort jamais, disent ceux qui le tracent. Quand on le trouve dans un endroit désert, on a pourtant l’impression d’être regardé.' },
};

const vallee = {
  rainK: 0, snowK: 0, burning: new Map(), fire: null, bolts: [], boltCD: 0, prevFlash: 0, spreadT: 0, burnAcc: 0, coldAcc: 0, coldMsg: 0,
  fish: null, fireNear: 0, firePan: 0, floaters: [], lastFloat: null, hooked: false,
  st() { const s = farm.s; if (!s.vallee) s.vallee = { char: {}, sigils: {}, flood: 0, peak: 0 }; return s.vallee; },
  base(w) { return w.baseWater ?? w.waterLevel; },

  // ------------------------------------------------------------ partie chargée
  load() {
    const w = game.world, V = this.st();
    w.baseWater = w.waterLevel;
    this.burning.clear(); this.fire = null; this.bolts.length = 0; this.fish = null; this.lastFloat = null;
    for (const k in V.char) { const o = w.objects[+k]; if (o && !o.gone) o.t = OBJ_INDEX.foudroye; }
    this.floaters = w.props.filter((p) => p.id === 'barque' && Math.abs(p.y - w.waterLevel) < 0.4).map((p) => ({ p, dy: p.y - w.waterLevel }));
    this.applyWater();
    w.objectsDirty = true;
    this.hookOnce();
  },
  applyWater() {
    const w = game.world, lvl = this.base(w) + this.st().flood;
    w.waterLevel = lvl;
    if (this.lastFloat === null || Math.abs(lvl - this.lastFloat) > 0.04) {
      this.lastFloat = lvl;
      for (const f of this.floaters) { f.p.y = lvl + f.dy; if (f.p.blk) f.p.blk.y = f.p.y; }
      if (this.floaters.length) farm.dirtyProps = true;
    }
  },

  // ------------------------------------------------------------ crues (au fil des heures)
  floodTick(dtH) {
    const V = this.st(), w = game.world, c = weather.cur, prev = V.flood;
    if (!w || strange.inEnvers()) return;
    const tgt = c.rain > 0.5 ? (c.storm > 0.5 ? 1.1 : 0.55) : 0;
    if (V.flood < tgt) V.flood = Math.min(tgt, V.flood + dtH * (c.storm > 0.5 ? 0.3 : 0.12));
    else if (V.flood > tgt) V.flood = Math.max(tgt, V.flood - dtH * (c.rain > 0.3 ? 0.03 : 0.1));
    if (V.flood > 0.05) { // cultures noyées
      const lvl = this.base(w) + V.flood;
      for (const k in farm.s.crops) {
        const cr = farm.s.crops[k];
        if (!cr.c || cr.dead || cr.tree) continue;
        const i = k.indexOf(','), x = +k.slice(0, i) + 0.5, z = +k.slice(i + 1) + 0.5;
        if (w.heightAt(x, z) < lvl - 0.05) { cr.drown = (cr.drown || 0) + dtH; if (cr.drown > 3) { cr.dead = true; farm.dirtyProps = true; } }
      }
    }
    if (prev < 0.3 && V.flood >= 0.3 && !game.player.underground) ui.subtitle('', '(L’eau monte : la rivière et les lacs débordent sur les prés du bas.)', 4.5);
    if (prev > 0.12 && V.flood <= 0.12 && V.peak > 0.3 && !game.player.underground) ui.subtitle('', '(La crue se retire des prés. Il reste de la boue et des herbes couchées.)', 4.5);
    V.peak = V.flood > 0.12 ? Math.max(V.peak || 0, V.flood) : 0;
  },

  // ------------------------------------------------------------ chaque image
  update(dt, eye, basis, sky) {
    const w = game.world, p = game.player, c = weather.cur, s = farm.s;
    this.applyWater();
    // pluie ou neige (en altitude, dans la grande vallée)
    const alt = eye[1] - this.base(w), sl = (w.snowLine || 1e4) - this.base(w);
    const a = w.designed && !p.underground ? smoothstep(sl - 26, sl - 2, alt) : 0;
    this.snowK = Math.max(c.rain * a, a * (0.42 * clamp((c.cloud - 0.55) * 2.5, 0, 1) + c.fog * 0.3));
    this.rainK = c.rain * (1 - a);
    // la foudre
    this.boltCD -= dt;
    if (weather.flash > this.prevFlash + 0.3 && c.storm > 0.5 && this.boltCD <= 0) { this.boltCD = 1.5; this.onBolt(); }
    this.prevFlash = weather.flash;
    for (const b of this.bolts) b.t -= dt;
    this.bolts = this.bolts.filter((b) => b.t > 0);
    // le feu
    this.fireUpdate(dt, eye, basis);
    // le froid, là-haut
    if (w.designed && alt > sl - 4 && !p.underground && !strange.inEnvers()) {
      p.food = Math.max(0, p.food - dt / w.dayLength * 70); // la faim vient deux fois plus vite
      const inside = w.covered(eye[0], eye[1], eye[2]), warm = inside || game.nearFire(p.pos) || this.fireNear > 0.6;
      if ((sky.night > 0.5 || (this.snowK > 0.35 && alt > sl + 25)) && !warm) {
        this.coldAcc += dt;
        if (!this.coldMsg) { this.coldMsg = 1; ui.subtitle('', '(Le froid vous mord les doigts. Il faudrait du feu, ou un toit.)', 4.5); }
        if (this.coldAcc > 2) { this.coldAcc = 0; const pn = strange.placeName(p.pos); play.hurt(2, null, 'Mort de froid' + (pn ? ' — ' + pn : ' en montagne')); }
      } else this.coldAcc = 0;
    } else { this.coldMsg = 0; this.coldAcc = 0; }
    // pêche sous la glace
    const F = this.fish;
    if (F) {
      if (Math.hypot(F.it.x - p.pos[0], F.it.z - p.pos[2]) > 6) this.fish = null;
      else if (F.bite > 0) { F.bite -= dt; if (F.bite <= 0) { this.fish = null; ui.subtitle('', '(Il s’est décroché.)', 2); } }
      else { F.t -= dt; if (F.t <= 0) { F.bite = 1.4; sound.bite && sound.bite(); ui.subtitle('', '(Ça mord ! Vite !)', 1.4); } }
    }
  },

  // ------------------------------------------------------------ foudre
  onBolt() {
    const w = game.world, p = game.player;
    if (p.underground || strange.inEnvers() || Math.random() > (weather.state === 'dry' ? 0.35 : 0.13)) return;
    let best = null, bs = -1;
    w.query(p.pos[0], p.pos[2], 170, (o, i) => {
      if (!o || o.gone || o.cleared || this.burning.has(i)) return;
      const T = OBJ_TYPES[o.t];
      if (!T || !STRIKE_TREES.has(T.id) || o.h < 7) return;
      const d = Math.hypot(o.x - p.pos[0], o.z - p.pos[2]);
      if (d < 14 || d > 170) return;
      const sc = (w.heightAt(o.x, o.z) + o.h) * (0.6 + Math.random() * 0.8);
      if (sc > bs) { bs = sc; best = [o, i]; }
    }, null);
    if (best) this.strike(best[0], best[1]);
  },
  strike(o, i) {
    const w = game.world, V = this.st(), top = w.objectY(o) + o.h, p = game.player, d = Math.hypot(o.x - p.pos[0], o.z - p.pos[2]);
    this.bolts.push({ x: o.x, z: o.z, y0: top, t: 0.42, seed: (Math.random() * 1e6) | 0 });
    weather.flash = 1.5;
    sound.thunder(clamp(1.2 - d / 200, 0.5, 1));
    game.shakeT = Math.max(game.shakeT || 0, d < 60 ? 0.6 : 0.25);
    V.char[i] = 1; o.t = OBJ_INDEX.foudroye; w.objectsDirty = true;
    entities.scare(o.x, o.z, 70);
    for (let k = 0; k < 26; k++) particles.spawn(o.x, top - Math.random() * o.h * 0.5, o.z, (Math.random() - 0.5) * 7, Math.random() * 5, (Math.random() - 0.5) * 7, [1, 0.85, 0.45, 1], 0.08, 0.5 + Math.random() * 0.5, 7, true);
    if (Math.random() < (weather.cur.rain < 0.3 ? 0.7 : 0.25)) this.ignite(o, i, true);
  },

  // ------------------------------------------------------------ incendie
  ignite(o, i, first) {
    if (this.burning.has(i) || o.gone) return;
    const T = OBJ_TYPES[o.t], tree = T.cat === 'Arbres';
    const w = game.world, b = { o, i, t: 0, life: tree ? 38 + Math.random() * 34 : 7 + Math.random() * 7, tree, x: o.x, z: o.z, y: w.objectY(o), h: Math.max(0.6, o.h) };
    this.burning.set(i, b);
    game.renderer.objFlag(i, 8);
    if (!this.fire) {
      this.fire = { n: 0, x: o.x, z: o.z };
      const p = game.player;
      if (Math.hypot(o.x - p.pos[0], o.z - p.pos[2]) < 260) setTimeout(() => ui.subtitle('', '(Le feu a pris dans les arbres !)', 3.5), first ? 900 : 0);
    }
    this.fire.n++;
  },
  burnOut(b, doused) {
    const w = game.world, V = this.st(), o = b.o;
    this.burning.delete(b.i);
    game.renderer.objFlag(b.i, 0);
    if (doused && b.t < b.life * 0.35) return; // éteint à temps : l'arbre s'en remettra
    if (b.tree || OBJ_TYPES[o.t].id === 'foudroye') { V.char[b.i] = 1; o.t = OBJ_INDEX.foudroye; }
    else { o.gone = true; o.cleared = true; farm.s.removed[b.i] = 1; }
    this.needRebuild = true; // regroupé : on ne reconstruit pas tous les objets à chaque arbre
  },
  fireUpdate(dt, eye, basis) {
    this.fireNear = 0;
    if (!this.burning.size) {
      if (this.needRebuild) { this.needRebuild = false; game.world.objectsDirty = true; }
      if (this.fire) {
        const p = game.player;
        if (Math.hypot(this.fire.x - p.pos[0], this.fire.z - p.pos[2]) < 450) ui.subtitle('', '(L’incendie s’est éteint. Des troncs noircis fument encore.)', 4.5);
        this.fire = null;
      }
      return;
    }
    const w = game.world, p = game.player, rain = weather.cur.rain, [wx, wz] = weather.rainWind(), wl = Math.hypot(wx, wz);
    if (this.needRebuild && performance.now() - (this.lastRebuild || 0) > 1500) { this.needRebuild = false; this.lastRebuild = performance.now(); w.objectsDirty = true; }
    this.spreadT -= dt;
    const spread = this.spreadT <= 0;
    if (spread) this.spreadT = 0.5;
    const add = [], done = [];
    let nearD = 1e9, nearB = null, hot = false;
    for (const b of this.burning.values()) {
      b.t += dt * (1 + rain * 3);
      if (spread && b.t > 3 && this.fire.n < 120) {
        const pr = 0.17 * (1 - rain * 0.95) * (this.fire.n > 70 ? 0.45 : 1);
        if (pr > 0.004) w.query(b.x, b.z, 7.5, (o, j) => {
          if (!o || o.gone || this.burning.has(j) || this.st().char[j]) return;
          const T = OBJ_TYPES[o.t];
          if (!T || !FLAMMABLE.has(T.id)) return;
          const dx = o.x - b.x, dz = o.z - b.z, d = Math.hypot(dx, dz);
          if (d > 7.5 || d < 0.01) return;
          const wind = wl > 0.3 ? 1 + 0.9 * (dx * wx + dz * wz) / (d * wl) : 1;
          if (Math.random() < pr * wind * (1 - d / 8.5)) add.push([o, j]);
        }, null);
      }
      if (b.t >= b.life) done.push(b);
      const d = Math.hypot(b.x - p.pos[0], b.z - p.pos[2]);
      if (d < nearD) { nearD = d; nearB = b; }
      if (d < (b.tree ? 2.4 : 1.3) && p.pos[1] < b.y + b.h && p.pos[1] > b.y - 1.5) hot = true;
    }
    for (const [o, j] of add) this.ignite(o, j);
    for (const b of done) this.burnOut(b);
    // ça brûle
    this.burnAcc = hot ? this.burnAcc + dt : 0;
    if (this.burnAcc > 0.5) { this.burnAcc = 0; const pn = strange.placeName(p.pos); play.hurt(8, nearB, 'Brûlé vif dans l’incendie' + (pn ? ' — ' + pn : '')); }
    // les bêtes s'enfuient
    if (Math.random() < dt * 0.5 && nearB) entities.scare(nearB.x, nearB.z, 45);
    // bruit du feu
    if (nearB) {
      this.fireNear = clamp(1 - nearD / 50, 0, 1);
      const ang = Math.atan2(nearB.x - eye[0], nearB.z - eye[2]);
      this.firePan = Math.sin(ang - Math.atan2(basis.r[0], basis.r[2]) + Math.PI / 2);
    }
    // flammèches et fumée (les plus proches)
    let n = 0;
    for (const b of this.burning.values()) {
      if (Math.abs(b.x - eye[0]) > 130 || Math.abs(b.z - eye[2]) > 130 || ++n > 30) continue;
      const R = Math.random;
      if (R() < dt * (b.tree ? 11 : 4)) particles.spawn(b.x + (R() - 0.5) * (b.tree ? 2.4 : 0.8), b.y + b.h * (0.25 + R() * 0.7), b.z + (R() - 0.5) * (b.tree ? 2.4 : 0.8), (R() - 0.5) * 0.8 + wx * 0.1, 2 + R() * 2.5, (R() - 0.5) * 0.8 + wz * 0.1, [1, 0.5 + R() * 0.35, 0.12, 1], 0.07, 0.6 + R() * 0.6, -0.6, true);
      if (R() < dt * (b.tree ? 2.2 : 0.8)) { particles.spawn(b.x + (R() - 0.5) * 2, b.y + b.h * 0.9, b.z + (R() - 0.5) * 2, wx * 0.25 + (R() - 0.5) * 0.5, 1.6 + R(), wz * 0.25 + (R() - 0.5) * 0.5, [0.2, 0.19, 0.18, 0.42], 0.6, 5 + R() * 3, -0.04, false); particles.list[particles.list.length - 1].grow = 4; }
    }
  },
  // l'arrosoir sur un arbre qui brûle
  douse(eye, f) {
    if (!this.burning.size) return false;
    const s = farm.s, px = eye[0] + f[0] * 2.4, pz = eye[2] + f[2] * 2.4;
    let best = null, bd = 4.2;
    for (const b of this.burning.values()) { const d = Math.hypot(b.x - px, b.z - pz); if (d < bd) { bd = d; best = b; } }
    if (!best) return false;
    if (s.water <= 0) { sound.click(); ui.subtitle('', '(L’arrosoir est vide. Vite, à l’eau !)', 2.5); play.cool = 0.4; return true; }
    s.water = Math.max(0, s.water - 1);
    play.canTilt = 0.5; play.cool = 0.45;
    sound.pour && sound.pour();
    for (let k = 0; k < 16; k++) particles.spawn(best.x + (Math.random() - 0.5), best.y + 1 + Math.random() * 2, best.z + (Math.random() - 0.5), (Math.random() - 0.5), 1.5 + Math.random(), (Math.random() - 0.5), [0.8, 0.82, 0.85, 0.5], 0.25, 1.2 + Math.random(), -0.3, false);
    best.water = (best.water || 0) + 1;
    if (best.water >= (best.tree ? 2 : 1)) this.burnOut(best, true);
    return true;
  },
  // quand on dort ou s'évanouit : l'incendie finit sans nous
  endFire() { for (const b of [...this.burning.values()]) this.burnOut(b); this.fire = null; },

  // ------------------------------------------------------------ dessin : éclairs et flammes
  draw(buf, cam, t) {
    if (!this.bolts.length && !this.burning.size) return;
    PE.buf = buf;
    PE.fl = FX_EMIT;
    for (const b of this.bolts) {
      if (Math.floor(b.t * 20) % 3 === 1) continue; // l'éclair vacille
      const rnd = mulberry32(b.seed), segs = 16, H = 110;
      PE.frame(0, 0, 0, 0, 1);
      let px = b.x + (rnd() - 0.5) * 34, pz = b.z + (rnd() - 0.5) * 34, py = b.y0 + H;
      for (let k = 1; k <= segs; k++) {
        const f = k / segs, j = (1 - f) * 8;
        const nx = k === segs ? b.x : lerp(px, b.x, 1 / (segs - k + 1)) + (rnd() - 0.5) * j, nz = k === segs ? b.z : lerp(pz, b.z, 1 / (segs - k + 1)) + (rnd() - 0.5) * j, ny = b.y0 + H * (1 - f);
        const dx = nx - px, dy = ny - py, dz = nz - pz, L = Math.hypot(dx, dy, dz);
        PE.box((px + nx) / 2, (py + ny) / 2, (pz + nz) / 2, 0.32, 0.32, L + 0.2, [2.4, 2.4, 2.8], TL.plain, Math.atan2(dx, dz), -Math.atan2(dy, Math.hypot(dx, dz)));
        if (k > 3 && k < segs - 2 && rnd() < 0.25) { const L2 = 4 + rnd() * 6, a = rnd() * TAU; PE.box(nx + Math.sin(a) * L2 / 2, ny - L2 * 0.3, nz + Math.cos(a) * L2 / 2, 0.18, 0.18, L2, [2, 2, 2.4], TL.plain, a, 0.5); }
        px = nx; py = ny; pz = nz;
      }
    }
    const L = [];
    for (const b of this.burning.values()) { const d = Math.hypot(b.x - cam[0], b.z - cam[2]); if (d < 170) L.push([d, b]); }
    L.sort((a, b) => a[0] - b[0]);
    // langues de feu : chacune monte en rétrécissant, jaune puis orange puis rouge, et recommence
    for (let q = 0; q < Math.min(45, L.length); q++) {
      const b = L[q][1], k = clamp(b.t / 4, 0.25, 1) * clamp((b.life - b.t) / 6, 0.2, 1), n = b.tree ? 12 : 4, R = b.tree ? 1.6 : 0.45;
      // du côté de la caméra : devant le feuillage (les arbres sont des images plates)
      const dd = L[q][0] || 1, off = b.tree ? Math.min(b.h * 0.28, dd * 0.5) : 0;
      PE.frame(b.x + (cam[0] - b.x) / dd * off, b.y, b.z + (cam[2] - b.z) / dd * off, 0, 1);
      for (let m = 0; m < n; m++) {
        const hs = hash2i(b.i, m, 7), hs2 = hash2i(m, b.i, 11), u = (t * (0.8 + hs * 0.6) + hs2) % 1;
        const a = hs * TAU + t * 0.4, rr = R * (0.35 + hs2 * 0.65) * (1 - u * 0.45);
        const y0 = b.tree ? b.h * (0.18 + hs2 * 0.45) : 0.05, fy = y0 + u * (b.tree ? b.h * 0.45 : 0.9);
        const sz = (b.tree ? 0.95 : 0.4) * k * (1 - u) * (0.6 + hs * 0.5);
        if (sz < 0.05) continue;
        const col = u < 0.3 ? [1.45, 1.05, 0.38] : u < 0.65 ? [1.4, 0.66, 0.18] : [1.05, 0.3, 0.08];
        PE.box(Math.cos(a) * rr, fy, Math.sin(a) * rr, sz * 0.7, sz * 1.6, sz * 0.7, col, TL.plain, a + u);
      }
    }
    PE.fl = 0;
  },
  lights(eye) {
    const out = [];
    if (this.burning.size) {
      const arr = [];
      for (const b of this.burning.values()) arr.push([Math.hypot(b.x - eye[0], b.z - eye[2]), b]);
      arr.sort((a, b) => a[0] - b[0]);
      for (let q = 0; q < Math.min(4, arr.length); q++) { const [d, b] = arr[q], f = 1 + Math.sin(performance.now() / 70 + b.i) * 0.15; out.push({ x: b.x, y: b.y + b.h * 0.5, z: b.z, r: b.tree ? 18 : 8, c: [1.5 * f, 0.7 * f, 0.22 * f], d }); }
    }
    for (const b of this.bolts) out.push({ x: b.x, y: b.y0 + 3, z: b.z, r: 70, c: [2.4, 2.4, 2.8], d: Math.hypot(b.x - eye[0], b.z - eye[2]) });
    return out;
  },
  inCrevasse() {
    const w = game.world, p = game.player;
    if (!w.crevasses) return false;
    for (const [[ax, az], [bx, bz]] of w.crevasses) if (segDist(p.pos[0], p.pos[2], ax, az, bx, bz) < 4.5) return true;
    return false;
  },

  // ------------------------------------------------------------ branchements (une fois, quand tout est chargé)
  hookOnce() {
    if (this.hooked) return;
    this.hooked = true;
    // secouer un arbre fruitier : ses fruits
    const _shake = game.shakeTree.bind(game);
    game.shakeTree = function (t) {
      const s = farm.s, o = t.o, H = HARVEST[OBJ_TYPES[o.t].id];
      if (!H || !H.fruit || s.shaken[t.idx] === s.day) return _shake(t);
      s.shaken[t.idx] = s.day;
      const y = this.world.objectY(o);
      for (let i = 0; i < 14; i++) particles.spawn(o.x + (Math.random() - 0.5) * 3, y + o.h * (0.5 + Math.random() * 0.4), o.z + (Math.random() - 0.5) * 3, (Math.random() - 0.5), -1, (Math.random() - 0.5), [0.35, 0.55, 0.2, 1], 0.06, 2 + Math.random(), 1.5, false);
      sound.shake && sound.shake();
      const [item, a, b] = H.fruit, n = a + Math.floor(Math.random() * (b - a + 1));
      if (n > 0) { farm.give(item, n); play.flyer(item, [o.x, y + 1.5, o.z], n); }
    };
    // dormir ou s'évanouir pendant un incendie : il finit sans nous
    const _skip = game.skipHours.bind(game);
    game.skipHours = function (h) { if (h > 0.5) vallee.endFire(); return _skip(h); };
    // le carnet des signes, dans l'onglet Légendes
    const _lb = ui.legendsBody.bind(ui);
    ui.legendsBody = function () {
      let body = _lb();
      const V = vallee.st(), ks = SIGIL_KINDS.filter((k) => V.sigils[k]);
      body += `<h4>Les signes relevés (${ks.length} / ${SIGIL_KINDS.length})</h4>`;
      body += ks.length ? ks.map((k) => `<button class="note" data-sigil="${k}">${esc(SIGIL_TEXT[k].titre)}</button>`).join('') : '<p class="hint">Aucun encore. On en trouve gravés sur des stèles, tracés en pierres dans l’herbe, dans la neige, sur la glace… et peints dans les galeries.</p>';
      setTimeout(() => $$('#satchel [data-sigil]').forEach((b) => (b.onclick = () => { const G = SIGIL_TEXT[b.dataset.sigil]; this.read(G.titre, G.texte, ''); })), 0);
      return body;
    };
  },
};

// ---------------------------------------------------------------- branchements
HOOKS.load.push(() => vallee.load());
HOOKS.update.push((dt, eye, basis, sky) => vallee.update(dt, eye, basis, sky));
HOOKS.draw.push((dyn, sh, cam, t) => vallee.draw(dyn, cam, t));
HOOKS.lights.push((eye) => vallee.lights(eye));
HOOKS.primary.push((eye, basis, held, it) => (it && it.tool === 'arrosoir' ? vallee.douse(eye, basis.f) : false));
{
  const _tick = farm.tick.bind(farm);
  farm.tick = function (dtH, ctx) { _tick(dtH, ctx); if (game.world === this.w) vallee.floodTick(dtH); };
  const _su = sound.update.bind(sound);
  sound.update = function (dt, o) { if (vallee.fireNear > (o.fire || 0)) { o.fire = vallee.fireNear; o.firePan = vallee.firePan; } return _su(dt, o); };
  const _hurt = play.hurt.bind(play);
  play.hurt = function (dmg, src, cause) { if (cause === 'Une mauvaise chute' && vallee.inCrevasse()) cause = 'Tombé au fond d’une crevasse du glacier'; return _hurt(dmg, src, cause); };
  const _lire = HOOKS.inter.lire;
  HOOKS.inter.lire = (it) => { const d = it.data || {}; if (d.text) { ui.read(d.text[0], d.text[1], d.text[2] || ''); sound.page && sound.page(); return; } return _lire && _lire(it); };
  const _loot = HOOKS.interPre.loot;
  HOOKS.interPre.loot = (it) => {
    if (it.data && it.data.table === 'crevasse') { const f = 'fouille_' + it.id; if (farm.s.flags[f]) { ui.subtitle('', '(Il n’y a plus rien. La glace garde le reste.)', 3); return true; } farm.s.flags[f] = 1; }
    return _loot ? _loot(it) : false;
  };
}
// les signes
HOOKS.inter.sigle = (it) => {
  const k = it.data.k, G = SIGIL_TEXT[k];
  if (!G) return;
  const V = vallee.st(), first = !V.sigils[k];
  if (first) { V.sigils[k] = farm.s.day; if (G.faith) faith.add(G.faith, 1); }
  const n = Object.keys(V.sigils).length;
  ui.read(G.titre, G.texte + (first ? `\n\n(Vous recopiez le signe dans votre carnet : ${n} sur ${SIGIL_KINDS.length}.)` : ''), it.data.big ? 'Tracé à même le sol, en grand : on ne le voit bien que de loin.' : 'Gravé dans la pierre.');
  sound.page && sound.page();
  if (first && n === SIGIL_KINDS.length && !farm.s.flags.douzeSignes) { farm.s.flags.douzeSignes = farm.s.day; setTimeout(() => ui.subtitle('', '(Les douze signes. Le treizième ne se trace pas, dit-on : il se porte.)', 5), 1500); }
};
// le refuge : on y dort
HOOKS.inter.refuge = () => game.trySleep('refuge');
// le trou dans la glace
HOOKS.inter.peche_glace = (it) => {
  if (!farm.count('canne')) { ui.subtitle('', '(Un trou rond dans la glace, l’eau noire dessous. Il faudrait une canne à pêche.)', 3.5); return; }
  const F = vallee.fish;
  if (!F) { vallee.fish = { it, t: 5 + Math.random() * 10, bite: 0 }; sound.splash && sound.splash(); ui.subtitle('', '(Vous laissez filer la ligne dans l’eau noire, et vous attendez.)', 3); return; }
  if (F.bite > 0) { vallee.fish = null; play.catchFish({ zone: 'lac_gele', x: it.x, y: it.y, z: it.z }); return; }
  ui.subtitle('', '(Rien encore. La ligne ne bouge pas.)', 2);
};

// ---- 11-zzz00-socle.js
// ============================================================================
//  SOCLE des nouveautés : ce qui doit attendre que la ferme (11-farm-play.js)
//  soit chargée, et ce que partagent les autres modules 11-zzz* :
//   - la journée de dix minutes ;
//   - savoir : ce que le personnage connaît (lieux, espèces vues, plantes
//     identifiées, recettes, mots des langues perdues, livres lus) ;
//   - corps : chutes, jambe cassée, saignements, pentes trop raides ;
//   - cine : les cinématiques (caméra, bandes noires, paroles) ;
//   - où l'on ne bâtit pas (villes, villages, lieux saints) ;
//   - les échelles des douves, la pêche dans les bassins.
// ============================================================================
DYN_PROPS.add('cascade'); DYN_PROPS.add('feu_geant'); DYN_PROPS.add('pierre_trois'); DYN_PROPS.add('piege_loup');

// ---------------------------------------------------------------- traduction : le module 14-i18n.js remplace T (T = function…)
// À appeler pour tout texte dessiné sur un canevas (les textes du DOM sont traduits automatiquement).
function T(s) { return s; }

// ---------------------------------------------------------------- l'étrange selon l'esprit du personnage
// Multiplicateur des probabilités des bizarreries du monde (1 = normal). Le module de l'esprit (la mentalité, cachée)
// le remplace par affectation (bizarrerie = function () {…}) : plus l'esprit est sombre, plus l'étrange se montre.
// Tout événement étrange ou rare devrait multiplier sa probabilité par bizarrerie().
function bizarrerie() { return 1; }
// Nombre de personnes tuées de la main du joueur (habitants nommés + autres gens que les modules comptent dans
// farm.s.stats.autresMeurtres)
function meurtresDuJoueur() { const s = farm.s; if (!s) return 0; return (s.dead || []).filter((d) => d.by === 'joueur').length + ((s.stats && s.stats.autresMeurtres) || 0); }

// ---------------------------------------------------------------- une journée : dix minutes
const JOUR_SECONDES = 600;
HOOKS.load.push(() => { if (game.world) game.world.dayLength = JOUR_SECONDES; });

// ---------------------------------------------------------------- où l'on ne bâtit pas (ni ne laboure, ni ne pose)
// renvoie la zone protégée qui couvre (x, z) (marge r en plus), ou null
function interditDeBatir(x, z, r) {
  const w = game.world;
  if (!w || !w.noBuild) return null;
  for (const P of w.noBuild) if (Math.hypot(x - P.x, z - P.z) < P.r + (r || 0)) return P;
  return null;
}

// ============================================================================
//  SAVOIR : ce que le personnage connaît (sauvegardé dans farm.s.savoir)
// ============================================================================
const savoir = {
  onLieu: [], onVu: [], onPlante: [], onRecette: [], onMots: [],
  S() {
    const s = farm.s;
    const K = s.savoir || (s.savoir = {});
    for (const k of ['lieux', 'vus', 'plantes', 'recettes', 'mots', 'lus']) if (!K[k]) K[k] = {};
    return K;
  },
  // -- les lieux où l'on est allé (les cartes ne montrent que ceux-là)
  lieuConnu(k) { return !!this.S().lieux[k]; },
  connaitreLieu(k) {
    const L = this.S().lieux;
    if (!k || L[k]) return false;
    L[k] = farm.s.day;
    for (const fn of this.onLieu) fn(k);
    return true;
  },
  // -- les espèces vues ou prises (bêtes : e.kind ; poissons : id d'objet ; plantes et arbres : id OBJ_TYPES)
  vu(id) { return this.S().vus[id] || 0; },
  voir(id, n) {
    if (!id) return false;
    const V = this.S().vus, first = !V[id];
    V[id] = (V[id] || 0) + (n || 1);
    if (first) for (const fn of this.onVu) fn(id);
    return first;
  },
  // -- les plantes que l'alchimiste a nommées (sans lui, on ne connaît que leur allure)
  planteConnue(id) { return typeof PLANT_LOOK === 'undefined' || !PLANT_LOOK[id] || !!this.S().plantes[id]; },
  identifier(id) {
    const P = this.S().plantes;
    if (P[id]) return false;
    P[id] = farm.s.day;
    for (const fn of this.onPlante) fn(id);
    return true;
  },
  // -- les recettes : celles de base, et celles qu'on a trouvées (ou apprises dans un livre, d'un habitant)
  recetteConnue(out) { return CRAFT_BASE.has(out) || !!this.S().recettes[out]; },
  apprendreRecette(out, source) {
    const R = this.S().recettes;
    if (CRAFT_BASE.has(out) || R[out]) return false;
    R[out] = source || 'essai';
    for (const fn of this.onRecette) fn(out, source);
    return true;
  },
  // -- les mots des langues perdues (aelin, gorrain)
  motConnu(lang, mot) { const M = this.S().mots[lang]; return !!(M && M[mot]); },
  motsConnus(lang) { return Object.keys(this.S().mots[lang] || {}); },
  apprendreMots(lang, liste) {
    const M = this.S().mots[lang] || (this.S().mots[lang] = {});
    let n = 0;
    for (const m of liste) if (m && !M[m]) { M[m] = farm.s.day; n++; }
    if (n) for (const fn of this.onMots) fn(lang, n);
    return n;
  },
  // -- les livres lus
  lu(id) { return !!this.S().lus[id]; },
  lire(id) { const L = this.S().lus; const first = !L[id]; L[id] = L[id] || farm.s.day; return first; },
};

// ce qu'on voit passe dans la mémoire : bêtes croisées, lieux traversés, plantes cueillies, poissons pris
{
  let lookT = 0;
  HOOKS.update.push((dt, eye, basis, sky, playing) => {
    if (!playing || !farm.s) return;
    lookT -= dt;
    if (lookT > 0) return;
    lookT = 0.5;
    const w = game.world, p = game.player, f = basis.f;
    for (const e of entities.list) {
      if (e.dead || e.removed || !e.kind) continue;
      const dx = e.x - eye[0], dz = e.z - eye[2], d = Math.hypot(dx, dz);
      if (d > 32 || d < 0.5) continue;
      if ((dx * f[0] + dz * f[2]) / d < 0.82) continue;
      if (e.hidden) continue;
      savoir.voir(e.kind);
    }
    for (const k in w.lm || {}) {
      const L = w.lm[k];
      if (L.under && !p.underground) continue;
      if (Math.hypot(L.x - p.pos[0], L.z - p.pos[2]) < Math.max(12, (L.r || 20) * 0.9)) savoir.connaitreLieu(k);
    }
    const t = game.target;
    if (t && (t.kind === 'pick' || t.kind === 'tree') && t.o) { const T = OBJ_TYPES[t.o.t]; if (T) savoir.voir(T.id); }
  });
  const _collect = play.collect.bind(play);
  play.collect = function (o, idx, H, p) { const ok = _collect(o, idx, H, p); if (ok && o && OBJ_TYPES[o.t]) savoir.voir(OBJ_TYPES[o.t].id); return ok; };
  const _give = farm.give.bind(farm);
  farm.give = function (id, n) { _give(id, n); if ((n === undefined || n > 0) && typeof FISH !== 'undefined' && FISH[id] && this.s) savoir.voir(id); };
}

// ============================================================================
//  CORPS : chutes, jambe cassée, saignements, pentes
// ============================================================================
const corps = {
  PENTE_MAX: 1.05,  // au-delà (46°), on ne monte plus
  PENTE_CHEMIN: 2.2, // sur un chemin de terre ou de pavés, on grimpe plus raide (il y a des marches taillées)
  PENTE_GLISSE: 1.45, // au-delà, on glisse
  C() { const s = farm.s; return s.corps || (s.corps = { jambe: 0, attelle: 0, saigne: 0, cause: '' }); },
  jambeCassee() { const C = this.C(); return C.jambe > farm.s.hours; },
  casserJambe(cause) {
    const C = this.C(), s = farm.s;
    const deja = this.jambeCassee();
    C.jambe = Math.max(C.jambe, s.hours + 48); C.attelle = 0;
    sound.impact && sound.impact('hard'); sound.hurt && sound.hurt(30);
    game.shakeT = 0.8;
    ui.subtitle('', deja ? '(La jambe cassée cède encore. La douleur vous coupe le souffle.)' : '(Un craquement sec. Votre jambe ne vous porte plus : elle est cassée.)', 4);
    if (deja) play.hurt(15, null, cause || 'Une mauvaise chute');
  },
  soignerJambe(total) {
    const C = this.C(), s = farm.s;
    if (!this.jambeCassee()) return false;
    C.jambe = total ? 0 : Math.min(C.jambe, s.hours + 12);
    return true;
  },
  // k : points de vie perdus par seconde (0.05 : une égratignure ; 1 : une artère)
  saigner(k, cause) {
    const C = this.C();
    C.saigne = Math.min(3, (C.saigne || 0) + k);
    if (cause) C.cause = cause;
  },
  saignement() { return this.C().saigne || 0; },
  panser() { const C = this.C(); if (!C.saigne) return false; C.saigne = 0; return true; },
  // atterrissage à la vitesse v (m/s)
  chute(v) {
    const p = game.player;
    if (BUFF.on('legerete') || p.riding) return;
    let k = 1;
    if (p.wading) k = 0.4;
    if (v <= 10.5) return;
    const dmg = Math.pow(v - 10.5, 1.5) * 3.4 * k;
    const casse = v > 13 && Math.random() < clamp((v - 13) / 6, 0, 1) * 0.85 * k;
    if (casse) this.casserJambe('Une mauvaise chute');
    if (v > 16.5 && Math.random() < 0.5) this.saigner(0.08 + (v - 16.5) * 0.04, 'Une mauvaise chute');
    play.hurt(dmg, null, v > 19 ? 'Une chute de très haut' : 'Une mauvaise chute');
  },
  // monter en douceur jusqu'à un point (échelles des douves, murs)
  hisser(to, dur) {
    if (this.hisse) return Promise.resolve();
    const p = game.player, from = p.pos.slice();
    return new Promise((res) => { this.hisse = { from, to: to.slice(), t: 0, dur: dur || 1.6, res }; sound.step('wood', 1); });
  },
  update(dt) {
    const p = game.player, s = farm.s, C = this.C();
    // se hisser
    const H = this.hisse;
    if (H) {
      H.t += dt;
      const k = Math.min(1, H.t / H.dur), up = Math.min(1, k / 0.75), fw = clamp((k - 0.6) / 0.4, 0, 1);
      p.pos = [lerp(H.from[0], H.to[0], fw), lerp(H.from[1], H.to[1] + 0.05, up * up * (3 - 2 * up)), lerp(H.from[2], H.to[2], fw)];
      p.vel = [0, 0, 0];
      if (Math.floor(H.t * 3) !== Math.floor((H.t - dt) * 3)) sound.step('wood', 0.8);
      if (k >= 1) { this.hisse = null; H.res(); }
    }
    // saignement : on meurt petit à petit, ou on s'en remet si ce n'est qu'une égratignure
    if (C.saigne > 0) {
      p.hp -= C.saigne * dt;
      if (C.saigne < 0.25) C.saigne = Math.max(0, C.saigne - dt * 0.0025);
      this.gouttesT = (this.gouttesT || 0) - dt;
      if (this.gouttesT <= 0) {
        this.gouttesT = clamp(1.2 / (C.saigne * 4 + 0.2), 0.15, 3);
        const w = game.world, y = w.groundAt(p.pos[0], p.pos[2], p.pos[1] + 0.3, 0.5);
        for (let i = 0; i < 2; i++) particles.spawn(p.pos[0] + (Math.random() - 0.5) * 0.4, p.pos[1] + 0.9, p.pos[2] + (Math.random() - 0.5) * 0.4, 0, -1, 0, [0.45, 0.02, 0.02, 1], 0.05, 0.7, 9, false);
        void y;
      }
      if (!this.ditSaigne || s.hours > this.ditSaigne + 2) { this.ditSaigne = s.hours; ui.subtitle('', C.saigne > 0.5 ? '(Vous perdez beaucoup de sang. Il faut un bandage, vite.)' : '(Vous saignez. Un bandage arrêterait ça.)', 3.5); }
      if (p.hp <= 0) game.die(C.cause || 'Mort de ses blessures, lentement');
    }
    if (this.jambeCassee()) {
      this.douleurT = (this.douleurT || 0) - dt;
      if (this.douleurT <= 0) { this.douleurT = 14 + Math.random() * 20; sound.hurtHuman ? sound.hurtHuman(0.3) : sound.hurt && sound.hurt(5); }
    } else if (C.jambe && C.jambe <= s.hours) { C.jambe = 0; C.attelle = 0; ui.subtitle('', '(Votre jambe vous porte de nouveau.)', 3); }
  },
};
// déplacements : jambe cassée, pentes trop raides, chutes (remplace l'ancien calcul des chutes)
{
  const _upd = Player.prototype.update;
  Player.prototype.update = function (dt, w, c) {
    if (game.kind !== 'farm' || !farm.s || this.fly) return _upd.call(this, dt, w, c);
    if (corps.hisse) { this.vel = [0, 0, 0]; return; }
    if (typeof cine !== 'undefined' && cine.on) c = { fwd: 0, right: 0, up: false, down: false, sprint: false };
    const casse = corps.jambeCassee() && !this.riding;
    const x0 = this.pos[0], y0 = this.pos[1], z0 = this.pos[2], vy0 = this.vel[1], g0 = this.onGround;
    const c2 = Object.assign({}, c, { onFall: null });
    const sp = this.mods.speed;
    if (casse) { c2.sprint = false; if (!this.swimming) c2.up = false; this.mods.speed = sp * (corps.C().attelle ? 0.55 : 0.4); }
    try { _upd.call(this, dt, w, c2); } finally { this.mods.speed = sp; }
    if (casse && this.onGround && Math.hypot(this.vel[0], this.vel[2]) > 0.5) this.eyeOffset += Math.sin(this.bobPhase * 2) * 0.012; // on boite
    // atterrissage
    if (!g0 && this.onGround && vy0 < -10.5 && !this.swimming) corps.chute(-vy0);
    // pentes : impossible de monter trop raide, et l'on glisse sur les parois
    if (this.onGround && !this.swimming && !this.underground) {
      const hN = w.heightAt(this.pos[0], this.pos[2]);
      if (Math.abs(this.pos[1] - hN) < 0.12) {
        const dx = this.pos[0] - x0, dz = this.pos[2] - z0, d = Math.hypot(dx, dz);
        if (d > 1e-4) {
          const h0 = w.heightAt(x0, z0);
          const m = w.matAt(this.pos[0], this.pos[2]), chemin = m === M_DIRT || m === M_COBBLE || m === M_SAND;
          if ((hN - h0) / d > (chemin ? corps.PENTE_CHEMIN : corps.PENTE_MAX) && Math.abs(y0 - h0) < 0.25) {
            this.pos[0] = x0; this.pos[2] = z0; this.pos[1] = Math.max(y0, h0);
            // on garde le glissé le long de la pente, pas la montée
            const n = w.normalAt(x0, z0), nl = Math.hypot(n[0], n[2]) || 1, gx = n[0] / nl, gz = n[2] / nl;
            const vd = this.vel[0] * gx + this.vel[2] * gz;
            if (vd < 0) { this.vel[0] -= vd * gx; this.vel[2] -= vd * gz; }
          }
        }
        const n = w.normalAt(this.pos[0], this.pos[2]), tan = Math.hypot(n[0], n[2]) / Math.max(0.05, n[1]);
        if (tan > corps.PENTE_GLISSE) {
          const nl = Math.hypot(n[0], n[2]) || 1, k = Math.min(1, (tan - corps.PENTE_GLISSE) * 2) * 3.2 * dt;
          const nx = this.pos[0] + n[0] / nl * k, nz = this.pos[2] + n[2] / nl * k;
          const [cx, cz] = this.collide(w, nx, nz, 0.3);
          this.pos[0] = cx; this.pos[2] = cz; this.pos[1] = w.groundAt(cx, cz, this.pos[1] + 0.3, 0.6);
        }
      }
    }
  };
}
HOOKS.update.push((dt, eye, basis, sky, playing) => { if (farm.s && !game.dying) corps.update(playing ? dt : 0); });
// soigner : bandage, attelle
HOOKS.primary.push((eye, basis, held, it, id) => {
  if (held) return false;
  if (id === 'bandage') {
    if (!corps.saignement()) { ui.subtitle('', '(Vous ne saignez pas.)', 2); return true; }
    farm.take('bandage', 1); corps.panser(); sound.equip && sound.equip();
    ui.subtitle('', '(Vous serrez le bandage. Le sang s’arrête.)', 3); play.cool = 0.8;
    return true;
  }
  if (id === 'attelle') {
    if (!corps.jambeCassee()) { ui.subtitle('', '(Vos jambes vont bien.)', 2); return true; }
    if (corps.C().attelle) { ui.subtitle('', '(L’attelle tient déjà la jambe.)', 2); return true; }
    farm.take('attelle', 1); corps.C().attelle = 1; corps.soignerJambe(false); sound.equip && sound.equip();
    ui.subtitle('', '(Vous immobilisez la jambe entre deux planchettes. Elle se remettra plus vite ; on marche un peu mieux.)', 4); play.cool = 0.8;
    return true;
  }
  return false;
});
// la mort lente a sa propre cause ; une nouvelle partie repart en bonne santé
HOOKS.load.push((saved) => { if (!saved && farm.s) farm.s.corps = { jambe: 0, attelle: 0, saigne: 0, cause: '' }; corps.hisse = null; });

// ---------------------------------------------------------------- les échelles des douves : on se hisse
HOOKS.inter.grimper = (it) => {
  const to = it.data && it.data.to;
  if (!to) return;
  if (corps.jambeCassee() && Math.random() < 0.6) { ui.subtitle('', '(Avec cette jambe, vous glissez des barreaux.)', 2.5); return; }
  corps.hisser(to, 1.5 + Math.max(0, to[1] - game.player.pos[1]) * 0.25);
};

// ---------------------------------------------------------------- pêche dans les bassins (sources chaudes, souterrains, temple)
{
  const _spot = strange.fishingSpot.bind(strange);
  strange.fishingSpot = function (eye, dir) {
    const r = _spot(eye, dir);
    if (r) return r;
    for (const P of game.world.pools || []) {
      if (Math.hypot(eye[0] - P.x, eye[2] - P.z) > 16) continue;
      const t = (P.y - eye[1]) / (dir[1] || -1e-3);
      if (!(t > 0 && t < 16)) continue;
      const x = eye[0] + dir[0] * t, z = eye[2] + dir[2] * t;
      const c = Math.cos(P.r || 0), sn = Math.sin(P.r || 0), dx = x - P.x, dz = z - P.z, lx = dx * c - dz * sn, lz = dx * sn + dz * c;
      if (Math.abs(lx) < P.w / 2 && Math.abs(lz) < P.d / 2) return { x, y: P.y, z, kind: P.kind };
    }
    return null;
  };
}

// ============================================================================
//  CINÉMATIQUES : une suite de plans filmés, bandes noires, paroles
//  cine.jouer([{ dur, de: { pos, look } | { pos, yaw, pitch }, a: {...}, texte, qui, fondu, debut(), fin(), joueur }], { passer })
//  - de / a : positions de caméra (a facultatif : plan fixe) ; look : point regardé
//  - orbite : { c:[x,y,z], r, h, a0, a1 } à la place de de/a
//  - joueur : dessine le personnage là où il se tient
//  Renvoie une promesse, résolue à la fin (ou quand on passe avec Espace).
// ============================================================================
const cine = {
  on: false, plans: null, i: 0, t: 0, res: null, opts: null, el: null, lastTxt: '',
  vue(pos, look) {
    const dx = look[0] - pos[0], dy = look[1] - pos[1], dz = look[2] - pos[2];
    return { pos: pos.slice(), yaw: Math.atan2(-dx, -dz), pitch: Math.atan2(dy, Math.hypot(dx, dz)) };
  },
  cam(k) {
    if (!k) return null;
    if (k.look) return this.vue(k.pos, k.look);
    return { pos: k.pos.slice(), yaw: k.yaw || 0, pitch: k.pitch || 0 };
  },
  jouer(plans, opts) {
    if (this.on) this.finir(true);
    this.plans = plans.filter(Boolean); this.i = -1; this.t = 0; this.opts = opts || {};
    this.on = true; game.noHand = true;
    this.dom(true);
    ui.close(true);
    this.next();
    return new Promise((res) => { this.res = res; });
  },
  next() {
    const P = this.plans[this.i];
    if (P && P.fin) try { P.fin(); } catch (e) { console.error(e); }
    this.i++; this.t = 0;
    const N = this.plans[this.i];
    if (!N) { this.finir(); return; }
    if (N.debut) try { N.debut(); } catch (e) { console.error(e); }
    this.texte(N.texte || '', N.qui || '');
    if (N.fondu === 'noir') $('#cine-veil').classList.add('on'); else $('#cine-veil').classList.remove('on');
  },
  finir(silent) {
    if (!this.on) return;
    const P = this.plans && this.plans[this.i];
    if (P && P.fin && !silent) try { P.fin(); } catch (e) { console.error(e); }
    this.on = false; game.noHand = false; this.plans = null;
    this.dom(false);
    const r = this.res; this.res = null;
    if (this.opts && this.opts.apres) try { this.opts.apres(); } catch (e) { console.error(e); }
    if (r) r();
  },
  passer() {
    if (!this.on || (this.opts && this.opts.passer === false)) return;
    // on joue les effets de tous les plans restants (sans les montrer)
    for (let k = this.i; k < this.plans.length; k++) { const P = this.plans[k]; if (k > this.i && P.debut) try { P.debut(); } catch (e) { console.error(e); } if (P.fin) try { P.fin(); } catch (e) { console.error(e); } }
    this.plans = []; this.i = 0;
    this.finir(true);
  },
  texte(t, qui) {
    const el = $('#cine-txt');
    if (!el) return;
    el.innerHTML = t ? (qui ? `<b>${esc(qui)}</b> — ` : '') + esc(t) : '';
    el.classList.toggle('on', !!t);
  },
  dom(on) {
    if (!$('#cine')) {
      const st = document.createElement('style');
      st.textContent = `#cine{position:fixed;inset:0;pointer-events:none;z-index:40}
#cine .bar{position:absolute;left:0;right:0;height:0;background:#000;transition:height .8s ease}
#cine .bar.t{top:0}#cine .bar.b{bottom:0}
#cine.on .bar{height:11vh}
#cine-txt{position:absolute;left:10%;right:10%;bottom:3.2vh;text-align:center;color:#e8e0cc;font:16px/1.4 Georgia,serif;opacity:0;transition:opacity .5s;text-shadow:0 1px 2px #000}
#cine-txt.on{opacity:1}#cine-txt b{color:#d8b878;font-weight:normal}
#cine-veil{position:absolute;inset:0;background:#000;opacity:0;transition:opacity 1s}
#cine-veil.on{opacity:1}
#cine-skip{position:absolute;right:14px;top:calc(11vh + 8px);color:#8a8070;font:12px Georgia,serif;opacity:0;transition:opacity .5s}
#cine.on #cine-skip{opacity:.7}
body.cine #hud,body.cine #hotbar,body.cine #dot,body.cine #pickups{visibility:hidden}`;
      document.head.appendChild(st);
      const d = document.createElement('div');
      d.id = 'cine';
      d.innerHTML = '<div id="cine-veil"></div><div class="bar t"></div><div class="bar b"></div><div id="cine-txt"></div><div id="cine-skip">Espace : passer</div>';
      document.body.appendChild(d);
    }
    $('#cine').classList.toggle('on', on);
    document.body.classList.toggle('cine', on);
    if (!on) { this.texte(''); $('#cine-veil').classList.remove('on'); }
    $('#cine-skip').style.display = this.opts && this.opts.passer === false ? 'none' : '';
  },
  update(dt) {
    if (!this.on) return;
    const P = this.plans[this.i];
    if (!P) { this.finir(); return; }
    this.t += dt;
    if (P.chaque) try { P.chaque(this.t, dt); } catch (e) { console.error(e); }
    if (this.t >= (P.dur || 3)) this.next();
    if (input.down('Space') && this.t > 0.6 && (this.i > 0 || this.t > 1)) this.passer();
  },
  camera() {
    if (!this.on) return null;
    const P = this.plans[this.i];
    if (!P) return null;
    const k0 = clamp(this.t / (P.dur || 3), 0, 1), k = k0 * k0 * (3 - 2 * k0);
    if (P.orbite) {
      const O = P.orbite, a = lerp(O.a0 || 0, O.a1 ?? (O.a0 || 0) + 0.6, k);
      const pos = [O.c[0] + Math.sin(a) * O.r, O.c[1] + (O.h ?? 3), O.c[2] + Math.cos(a) * O.r];
      return this.vue(pos, O.look || O.c);
    }
    const A = this.cam(P.de), B = this.cam(P.a) || A;
    if (!A) return null;
    let dy = B.yaw - A.yaw;
    while (dy > Math.PI) dy -= TAU;
    while (dy < -Math.PI) dy += TAU;
    const pos = [lerp(A.pos[0], B.pos[0], k), lerp(A.pos[1], B.pos[1], k), lerp(A.pos[2], B.pos[2], k)];
    const shake = P.secousse ? P.secousse * (1 - k0 * 0.5) : 0;
    if (shake) { const t = game.time; pos[0] += Math.sin(t * 37) * shake; pos[1] += Math.sin(t * 41) * shake; }
    return { pos, yaw: A.yaw + dy * k, pitch: lerp(A.pitch, B.pitch, k) };
  },
  // le personnage lui-même, vu de l'extérieur
  rigJoueur() {
    const fem = !!farm.s.fem;
    const key = fem ? 'f' : 'm';
    if (this._rig && this._rigK === key) return this._rig;
    this._rigK = key;
    this._rig = humanRig(fem ? { skin: '#e2b894', hair: '#5a3a22', hairStyle: 'long', top: '#7a6a58', bottom: '#4a3c30', dress: true, bust: 0.5, hips: 0.5 } : { skin: '#dcb08a', hair: '#4a3020', top: '#6a5a48', bottom: '#3a3830', hat: 'paille', beard: 'courte' });
    return this._rig;
  },
};
HOOKS.update.push((dt) => cine.update(dt));
HOOKS.camera.push(() => cine.camera());
HOOKS.draw.push((buf, sbuf, cam, t) => {
  if (!cine.on) return;
  const P = cine.plans && cine.plans[cine.i];
  if (!P || !P.joueur) return;
  const p = game.player, r = cine.rigJoueur();
  poseHuman(r, { move: 0, t, lookY: 0 });
  drawRig(buf, r, p.pos[0], p.pos[1], p.pos[2], p.yaw + Math.PI, 1, 0);
  if (sbuf) drawShadow(sbuf, p.pos[0], p.pos[1], p.pos[2], 0.34);
});
// pendant une cinématique : ni clic, ni touche E (Espace pour passer)
HOOKS.primary.unshift(() => cine.on);
HOOKS.secondary.unshift(() => cine.on);
// (game est défini plus loin, dans 13-main.js : on s'y branche au premier chargement)
HOOKS.load.unshift(() => {
  if (game._socle) return;
  game._socle = true;
  const _interact = game.interact.bind(game);
  game.interact = function () { if (cine.on || corps.hisse) return; return _interact(); };
  const _die = game.die.bind(game);
  game.die = function (cause) { if (cine.on) cine.finir(true); corps.hisse = null; return _die(cause); };
});

// ---- 12-ui.js
// ============================================================================
//  INTERFACE : menus, options, panneau de l'éditeur, HUD, fichiers
