const DEFAULT_SETTINGS = { sens: 1.0, fov: 90, pixel: 270, dither: true, bands: true, volume: 0.6, ambVolume: 0.5, invertY: false, viewDist: 340, showFps: false, gamma: 1.0, subs: true, aimDot: false };
